#!/usr/bin/env python3
"""Build the public GFG pages. Contains public product copy and fictional examples only."""
from pathlib import Path
from html import escape
import json

ROOT = Path(__file__).resolve().parents[1]
ORIGIN = "https://zombiewalrusdong.github.io/grants-for-good-pages/"
REPOSITORY = "https://github.com/ZombieWalrusDong/grants-for-good-pages"
VERSION = "0.135.2"


def wordmark():
    return '<a class="wordmark" href="index.html" aria-label="Grants for Good home"><img src="assets/mark.svg" alt="" width="42" height="42"><span>grants for<strong>good.</strong></span></a>'


def page(filename, title, description, body, active=""):
    navigation = [("product.html", "The workspace"), ("workflow.html", "How it works"), ("help.html", "Help")]
    links = ''.join(f'<a href="{url}"'+(' aria-current="page"' if active == url else '')+f'>{label}</a>' for url,label in navigation)
    full_title = "Grants for Good — Good work, well supported." if filename == "index.html" else title + " · Grants for Good"
    html = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
{'<base href="'+ORIGIN+'">' if filename == "404.html" else ""}<title>{escape(full_title)}</title><meta name="description" content="{escape(description, quote=True)}">
<meta name="theme-color" content="#163d32"><link rel="canonical" href="{ORIGIN}{filename if filename != 'index.html' else ''}">
<meta property="og:type" content="website"><meta property="og:site_name" content="Grants for Good"><meta property="og:title" content="{escape(full_title, quote=True)}"><meta property="og:description" content="{escape(description, quote=True)}"><meta property="og:url" content="{ORIGIN}{filename if filename != 'index.html' else ''}"><meta property="og:image" content="{ORIGIN}assets/social-card.png"><meta property="og:image:alt" content="Grants for Good. Good work, well supported.">
<meta name="twitter:card" content="summary_large_image"><link rel="icon" type="image/svg+xml" href="assets/mark.svg"><link rel="icon" type="image/png" sizes="64x64" href="assets/icon-64.png"><link rel="apple-touch-icon" href="assets/icon-180.png"><link rel="stylesheet" href="assets/site.css"><script src="assets/site.js" defer></script>
</head><body><a href="#main" class="skip">Skip to content</a><header class="site-header"><div class="wrap header-inner">{wordmark()}<button type="button" class="menu-toggle" aria-controls="primary-navigation" aria-expanded="false">Menu</button><nav class="nav" id="primary-navigation" aria-label="Primary">{links}<a class="button small" href="get-started.html"{' aria-current="page"' if active == 'get-started.html' else ''}>Get started</a></nav></div></header>
<main id="main">{body}</main>
<footer class="site-footer"><div class="wrap"><div class="footer-top">{wordmark()}<nav class="footer-links" aria-label="Footer"><a href="product.html">Workspace</a><a href="workflow.html">Workflow</a><a href="get-started.html">Getting started</a><a href="help.html">Help & support</a><a href="privacy.html">Privacy</a><a href="terms.html">Terms</a><a href="brand.html">Brand kit</a></nav></div><div class="footer-bottom"><p>Good work, well supported.</p><p>A project by Matt Cornett · Private beta</p></div></div></footer></body></html>'''
    (ROOT / filename).write_text(html, encoding="utf-8")


def hero(eyebrow, heading, description):
    return f'<div class="page-hero"><div class="wrap"><p class="eyebrow">{eyebrow}</p><h1>{heading}</h1><p class="lede">{description}</p></div></div>'


def article(contents, sections):
    links = ''.join(f'<a href="#{ident}">{label}</a>' for ident,label in contents)
    return '<div class="wrap page-grid"><aside class="page-aside" aria-label="On this page"><strong>On this page</strong>'+links+'</aside><div class="prose">'+sections+'</div></div>'


def section(ident, title, content):
    return f'<section id="{ident}"><h2>{title}</h2>{content}</section>'


def icon(kind):
    paths = {
        "research": '<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5M7 10h6m-3-3v6"/>',
        "review": '<path d="M8 4h12v16H4V8m4-4v4H4m4 0V4m4 9 2 2 4-5"/>',
        "report": '<path d="M5 3h10l4 4v14H5zm10 0v5h4M8 12h8M8 16h6"/>',
    }
    return '<span class="feature-icon"><svg viewBox="0 0 24 24" aria-hidden="true">'+paths[kind]+'</svg></span>'


def faq(question, answer):
    return '<details class="faq"><summary>'+question+'</summary><p>'+answer+'</p></details>'


def main():
    preview = '''<div class="preview-wrap"><div class="app-preview" aria-label="Illustrative project match list with fictional organizations"><div class="preview-titlebar"><strong>g. &nbsp; Your workspace</strong><span class="window-dots" aria-hidden="true"><i></i><i></i><i></i></span></div><div class="preview-body"><div class="preview-project">A little more possibility.</div><p class="caption">Fieldnotes Nature Collective · Outdoor learning</p><div class="mini-nav"><span>Today</span><span class="selected">Funders</span><span>Work</span><span>Team</span></div><div class="preview-row"><div><strong>Canopy Learning Trust</strong><small>Outdoor science grants</small><small><span class="chip">Promising fit</span></small></div><div class="fit-number">91<small>95% assessed</small></div></div><div class="preview-row"><div><strong>River & Reed Foundation</strong><small>Community learning fund</small><small><span class="chip future">Closed round · future lead</span></small></div><div class="fit-number">79<small>80% assessed</small></div></div><div class="preview-row"><div><strong>Meadow Community Fund</strong><small>Application route to confirm</small><small><span class="chip">Needs discovery</span></small></div><div class="fit-number">77<small>60% assessed</small></div></div></div></div><div class="preview-note"><svg viewBox="0 0 30 30" fill="none" aria-hidden="true"><circle cx="15" cy="15" r="13" stroke="#6d8f4b"/><path d="m9 15 4 4 8-8" stroke="#28664e" stroke-width="1.8"/></svg><span><strong>The next step is clear.</strong>Research, evidence, and your team’s decision in one place.</span></div><p class="caption">Illustrative workspace. All organizations and findings shown are fictional.</p></div>'''
    home = f'''<div class="wrap"><section class="hero"><div><span class="pill">A workspace for grant teams · Private beta</span><h1>Good work,<br><em>well supported.</em></h1><p class="lede">Bring client knowledge, funder research, and your team’s next steps together. Turn a promising lead into a recommendation you can stand behind.</p><div class="actions"><a href="product.html#tour" class="button">Explore the workspace</a><a href="workflow.html" class="button secondary">See how it works</a></div><p class="caption">Runs on your computer. Shares through your team’s Google Drive.</p></div>{preview}</section><div class="trust-strip"><span>Your own Google sign-in</span><span>Research with a source behind it</span><span>Human decisions stay human</span></div><section class="section"><div class="section-head"><p class="eyebrow">From a lead to a next step</p><h2>Less scattered research.<br>More considered decisions.</h2><p>A useful funder match is more than a name and a number. Keep the fit, the evidence, the timing, and the work that follows connected.</p></div><div class="three-up"><article class="feature">{icon('research')}<h3>Know where to look.</h3><p>Start with the client and the funding need. Screen broadly, verify the questions that matter, then spend your research time on the strongest candidates.</p><a class="text-link" href="workflow.html#research">Explore the research flow</a></article><article class="feature">{icon('review')}<h3>See why it fits.</h3><p>Six weighted criteria, source-linked findings, and visible unknowns. A closed round can stay on the list as a worthwhile future prospect.</p><a class="text-link" href="workflow.html#fit">Understand fit and timing</a></article><article class="feature">{icon('report')}<h3>Make the work useful.</h3><p>Bring the shortlist to your colleague in a visual client report, with full funder profiles and a linked spreadsheet. Keep tasks and discussions close by.</p><a class="text-link" href="product.html#handoff">See the handoff</a></article></div></section></div><section class="dark-section"><div class="wrap split"><div><p class="eyebrow">Built for working together</p><h2>One place for the context.</h2><p>For grant researchers, writers, and small nonprofit teams who need to know what’s been found, what’s been decided, and what happens next.</p><a class="button lime" href="product.html">Meet the workspace</a></div><ul class="principle-list"><li><strong>Client knowledge comes first.</strong><p>Keep the organization, program, budget need, contacts, notes, and unanswered questions connected.</p></li><li><strong>Evidence stays in view.</strong><p>Separate a useful lead from a verified rule. Keep the source and the date with the finding.</p></li><li><strong>The team stays in control.</strong><p>Research suggestions, human review, and authorization to act are separate decisions.</p></li></ul></div></section><div class="wrap"><section class="section-cta"><div><p class="eyebrow">A considered next step</p><h2>Start with the right context.</h2><p>See what you need to join a shared workspace.</p></div><a class="button" href="get-started.html">Getting started</a></section></div>'''
    page("index.html", "Home", "A local-first workspace for grant research, client knowledge, project work, and clear, evidence-led recommendations.", home)

    tour = '''<section class="wrap section" id="tour"><div class="section-head"><p class="eyebrow">A small look inside</p><h2>Useful detail.<br>At a glance.</h2><p>Try the filters and select a funder. This interactive illustration shows how fit, timing, and unanswered questions can sit together.</p></div><div class="tour-shell" data-tour><div class="tour-top"><div><h2>Fieldnotes Nature Collective</h2><p>Outdoor learning · Fictional product illustration</p></div><div class="tour-tabs" role="group" aria-label="Illustrative match filters"><button type="button" data-tour-filter="all" aria-pressed="true">All prospects</button><button type="button" data-tour-filter="future" aria-pressed="false">Future cycles</button><button type="button" data-tour-filter="discovery" aria-pressed="false">Needs discovery</button></div></div><div class="tour-content"><div class="tour-matches"><p class="eyebrow">Select a funder</p><div data-tour-list><p>Enable JavaScript to explore this fictional example. The rest of this site works without it.</p></div></div><div class="tour-detail" data-tour-detail aria-live="polite" aria-atomic="true"><h3>See the reasons behind the rating.</h3><p>A score is a starting point. The evidence, assessed coverage, and next step tell you how much confidence to place in it.</p></div></div></div><p class="legend">These are fictional organizations, illustrative findings, and example scores—not real funding opportunities. This tour does not read or save workspace data.</p></section>'''
    product = hero("The workspace", "Room for the whole picture.", "Client knowledge, research, project work, and a useful handoff—connected in one local workspace.")+tour
    product += article([("client", "Client knowledge"),("research", "Funder research"),("team", "Working together"),("handoff", "Reports & handoffs"),("boundaries", "Where it runs")],
        section("client", "Start with the organization.", "<p>Build a shared picture of the client and their programs: legal identity, geography, operating history, funding needs, document links, contacts, and conversations. Keep unknowns visible instead of filling them with assumptions.</p><p>Project-specific context carries into research so you are not retyping the client’s need for every prospect.</p>")+
        section("research", "A shortlist with reasons.", "<p>Explore independent funder research and connected Instrumentl matches in their own views. Use funder profiles to read saved source material, application routes, program information, and available IRS filing history.</p><p>Six-factor assessments show the score, the evidence coverage, and what still needs discovery. Current and future-cycle leads remain distinguishable. Optional open-chat research uses a prepared packet; the app does not run an unattended model job.</p>")+
        section("team", "Keep the ordinary work close.", "<div class=\"feature-pair\"><article><h3>Plans, tasks, and dates</h3><p>Daily plans, a work board, calendar, checklists, owners, and follow-up tasks keep the next action visible.</p></article><article><h3>A conversation with context</h3><p>Threaded project discussions, questions, activity, personal unread counts, and record history help colleagues stay caught up.</p></article></div><p>Application preparation, reusable content, and client follow-up live alongside research. Connected external actions follow the app’s separate permission and approval rules; a research score is not permission to apply or change an outside account.</p>")+
        section("handoff", "A report worth opening.", "<p>Build a visual client report with a ranked shortlist and linked, self-contained funder profiles. Include the saved fit narrative, timing, funding routes, findings, and source links rather than handing over a wall of unexplained scores.</p><p>The report-and-spreadsheet ZIP keeps the portable HTML and linked Excel workbook together. Extract both files into the same folder. The saved report can be read without an app login; following external source links requires internet access.</p><div class=\"note\">A closed round can still be a good future lead. Keep the timing qualification, the next action, and any published dates with it. Unknown future dates stay unknown.</div>")+
        section("boundaries", "Local app. Shared context.", "<p>Each person runs the app on their own computer and signs in with their own Google account. Workspace records sync through a Google Drive folder shared by the team. Work can be saved locally while offline; sharing resumes when the connection returns.</p><p>This public site is the product and support home. It does not host your client workspace. The app is a private beta, and Windows onboarding, connected actions, and live team workflows still need real-world validation before a 1.0 claim.</p><a class=\"button\" href=\"get-started.html\">Set up your workspace</a>"))
    page("product.html", "The workspace", "Explore client context, six-factor funder research, team project tools, and portable client reports in Grants for Good.", product, "product.html")

    workflow = hero("How it works", "Research that adds up.", "Know the client. Find the strongest prospects. Settle the questions that change a decision. Hand over something your colleague can use.")
    flow = section("context", "Begin with the client and the need.", "<p>Record who can apply, who the program serves, where it operates, what needs funding, and what is still unconfirmed. A draft intake produces provisional findings. Confirm the important facts before treating a match as ready to pursue.</p>")
    flow += section("research", "Three passes. A clearer shortlist.", "".join(f'<div class="step"><span class="step-marker">{n}</span><div><h3>{title}</h3><p>{body}</p></div></div>' for n,title,body in [
        (1,"Screen broadly", "Review the available project evidence across the selected matches. Separate strong candidates, questions worth resolving, future cycles, and weak leads. This pass uses the packet’s evidence without new browsing."),
        (2,"Verify the deciding questions", "Open current funder guidance for the promising routes. Confirm applicant eligibility, geography, permitted costs, application access, and timing. Spend time on uncertainties that could change the recommendation."),
        (3,"Research the finalists", "Build a fuller picture of the funder, route, fit, calendar, and remaining qualifications. Preserve a readable rationale and source trail, then bring the findings into the team’s review and client report.")]))
    flow += '<div class="callout"><strong>Research runs in your open chat, when you ask for it.</strong><p>The app prepares assignments and imports structured results. It keeps the saved findings and progress, but it does not secretly run a model in the background. Human review stays separate from importing suggestions.</p></div>'
    flow += section("fit", "A score needs context.", '''<p>The six-factor rubric rates known criteria from 1 to 5. Unknowns stay unknown. Only the known criteria contribute to the reweighted score, and coverage tells you how much of the rubric has actually been assessed.</p><table class="status-table"><caption class="eyebrow">The six-factor rubric</caption><thead><tr><th scope="col">Criterion</th><th scope="col">Weight</th><th scope="col">The question</th></tr></thead><tbody><tr><td>Mission & program</td><td>25%</td><td>Does this work belong in the funder’s stated interests?</td></tr><tr><td>Eligibility & geography</td><td>25%</td><td>Can this applicant and service area qualify?</td></tr><tr><td>Comparable giving</td><td>20%</td><td>Is there evidence of relevant past support?</td></tr><tr><td>Funding value</td><td>15%</td><td>Is the likely support worthwhile relative to the work?</td></tr><tr><td>Feasibility</td><td>10%</td><td>Is the application route practical?</td></tr><tr><td>Relationships</td><td>5%</td><td>Is there a known, useful connection?</td></tr></tbody></table><p>A high score with little evidence is not the same as a well-supported recommendation. Read coverage, confidence, eligibility, reasons, and sources together. Eligibility limits can cap a score; an evidenced contradiction with a published rule can disqualify a route.</p><p>Timing is a separate question. A closed application window is not, by itself, a permanent disqualification. Keep a good future lead and record when to check again—without guessing next year’s deadlines.</p>''')
    flow += section("decision", "Review, decide, and record the next step.", "<p>Suggestions are not human approval. Review the findings, make the recommendation your own, and record a clear next step: pursue, resolve a question, revisit a future cycle, or set the route aside.</p><p>Where an external connection is configured, any action in another service must pass its separate authorization rules. Importing research does not submit an application, contact a funder, or authorize an Instrumentl change.</p>")
    flow += section("report", "Make a useful handoff.", "<p>Choose the researched routes that belong in the client report. Keep promising future prospects alongside current options, with the qualification and calendar information visible. Use the visual report for the first read and the linked funder profiles for depth.</p><p>The source trail and earlier detailed research remain useful. A broad rescreen does not make an earlier funder dossier disappear; check its age and confirm any rule that may have changed.</p><a class=\"button\" href=\"product.html#handoff\">Explore reports and handoffs</a>")
    workflow += article([("context","Client context"),("research","Three research passes"),("fit","The six-factor rubric"),("decision","Human decisions"),("report","The handoff")],flow)
    page("workflow.html","How it works","Understand GFG’s client-first research workflow, broad screening, targeted verification, six-factor scoring, and human review.",workflow,"workflow.html")

    start = hero("Getting started", "Your computer.<br>Your team’s workspace.", "Grants for Good is currently shared directly with invited beta teams. There is no public account signup or hosted workspace on this website.")
    start += article([("installation","Get an installation"),("join","Join the team"),("demo","Try fictional data"),("updates","Updates & backups"),("version","Current version")],
        section("installation","Get the right installation.","<p>Ask the person who invited you for the app package and the team’s workspace folder link. A preconfigured installation includes the Google desktop app configuration; it must never include someone else’s sign-in tokens or client records.</p><div class=\"feature-pair\"><article><h3>Windows</h3><p>Use the supplied 64-bit Windows package, extract the ZIP, and double-click <strong>Grants for Good.bat</strong>. The full Windows package includes Python. Read the package’s START HERE instructions.</p></article><article><h3>Linux</h3><p>Use Python 3.10 or newer. Open the supplied app folder and use its Linux launcher, or run <code>python3 app.py</code>. Keep the app running while you work in your browser.</p></article></div><p>These pages do not distribute the private application source or a preconfigured team installer. Use the package supplied by your workspace owner.</p>")+
        section("join","Join once, with your own Google account.","<ol><li><strong>Open the app.</strong> It starts a local web address in your browser. That address belongs to your computer, not this public website.</li><li><strong>Confirm the workspace folder.</strong> Use the Google Drive folder shared by your team. An invited installer may already have it filled in.</li><li><strong>Sign in with your own Google account.</strong> The account needs edit access to the workspace folder. Read the <a href=\"privacy.html#google\">Drive permission explanation</a> before consenting.</li><li><strong>Check sharing.</strong> Post a harmless test message and ask a colleague to reply. Confirm that both computers receive it before relying on the workspace.</li></ol><p>Your workspace administrator may need to add your Google account to the beta’s permitted users. If Google refuses the saved sign-in, use the app’s sign-in-again option.</p>")+
        section("demo","Try it without client data.","<p>The website’s <a href=\"product.html#tour\">interactive product illustration</a> is safe to explore immediately. It uses fictional funders and does not connect to any account.</p><p>For the full installed app, the supplied source installation supports a separate fictional demo: from its app folder, run <code>python3 app.py --demo --port 8766</code>. Do not use real client data in a demo workspace.</p>")+
        section("updates","Keep both copies current.","<p>Use the app’s update instructions and packages supplied by the workspace owner. Close the app before replacing its files. Update both teammates’ installations before using newly shared record types.</p><p>If your local app is already running, the launcher offers Open, Restart, or Cancel. On Linux, <code>python3 app.py --restart</code> restarts the verified copy. Refresh your browser after an update.</p><p>Keep backups of the local workspace and shared records. Uninstalling the app, deleting a workspace, and revoking Google access are different actions; see <a href=\"privacy.html#control\">your data controls</a>.</p>")+
        section("version","Current beta: v"+VERSION+".","<p>As of November 18, 2026, v0.135.2 restores the sign-in-again action when Google rejects an existing session. The preceding release added visual research reports, linked funder profiles, and report-and-spreadsheet packages.</p><p>Beta status means real-world validation is still in progress. This website’s publication is not a 1.0 release and does not change your Google consent settings or your installed copy.</p><a class=\"button secondary\" href=\"help.html\">Find help</a>"))
    page("get-started.html","Getting started","Join an invited GFG beta workspace on Windows or Linux, use your own Google sign-in, and keep the shared workspace current.",start,"get-started.html")

    help_body = hero("Help & support","A little clarity<br>goes a long way.","Start with the common questions. If something is still wrong, a clear bug report helps us fix the right thing.")
    questions = faq("Is this where I sign in to my workspace?","No. Open the installed app on your computer, then sign in there with your own Google account. This website explains the product; it does not host your client records.")
    questions += faq("Do I need Google Drive for the product tour?","No. The tour uses fictional examples in your browser. A shared, installed team workspace uses Google Drive and requires your own sign-in.")
    questions += faq("Why does Google ask for broad Drive access?","The current beta requests full Google Drive permission to support automatic discovery of team data files. Its workspace features are designed around the chosen team folder, but the Google grant is broader than that folder. See the <a href=\"privacy.html#google\">full permission explanation</a>.")
    questions += faq("Does a score mean we should apply?","No. Scores are suggestions supported by varying amounts of evidence. Read coverage, confidence, reasons, eligibility, and timing. Human review and authorization to act are separate.")
    questions += faq("Why are some factors unknown?","There is not enough evidence to rate them responsibly. The app reweights the known factors and shows coverage. Unknown does not mean average, and it should come with a concrete discovery step.")
    questions += faq("What happens to a good lead when the round is closed?","It can remain a future-cycle prospect. Record the closed round, the next source check, and any published future dates. Do not treat an old deadline as a confirmed new one.")
    questions += faq("Can I use the app offline?","The installed app saves work locally. Sharing needs an internet connection and the app running; pending work syncs when the connection is restored. Keep backups and check for conflicts after reconnecting.")
    questions += faq("Can a colleague open an exported report without the app?","Yes. Extract the report package and keep the HTML and spreadsheet together. Saved funder profiles travel inside the HTML report. Source websites still need internet access. Share the report only with its intended recipients.")
    questions += faq("Why am I being asked to sign in again?","A saved Google authorization may have expired or been revoked. Open the app’s Google connection and sign in again. A workspace administrator may also need to check the beta account list. Do not send anyone your password or authorization tokens.")
    questions += faq("Will this replace every part of Instrumentl?","GFG focuses on shared client context, research, review, project work, and handoffs. Instrumentl remains a separate service, with its own subscription, permissions, and account rules. Connections and supported actions depend on the team’s configuration.")
    help_body += article([("questions","Common questions"),("report","Report a problem"),("privacy-request","Private requests")],section("questions","The common questions.",questions)+section("report","Help us reproduce it.",f'<p>For an app bug, use the in-app feedback tool when available. You can also <a href="{REPOSITORY}/issues/new?template=bug-report.yml">report a public, non-sensitive bug</a> on this website’s GitHub repository.</p><ul><li>What were you trying to do?</li><li>What happened, and what did you expect?</li><li>Which app version and operating system are you using?</li><li>Can you reproduce it using a fictional example?</li></ul><div class="callout"><strong>Public issues are public.</strong><p>Leave out client names, project records, screenshots containing confidential information, folder links, account details, credentials, and sign-in tokens. Share sensitive details privately with your workspace owner.</p></div>')+section("privacy-request","For a private or account question.",' <p>Contact the workspace owner who supplied your installation through your existing private contact channel. They manage access to the shared folder and can coordinate account or record-removal requests.</p><p>Project developer: <a href="https://github.com/ZombieWalrusDong">Matt Cornett on GitHub</a>. Do not post private client information in a public issue. See the <a href="privacy.html">privacy policy</a> for the app’s data handling and controls.</p>'))
    page("help.html","Help & support","Answers about GFG setup, Google Drive access, unknown scores, future-cycle leads, report sharing, and reporting bugs safely.",help_body,"help.html")

    privacy = hero("Privacy policy","Your work deserves care.","What Grants for Good stores, what it shares, and the controls available to you. Last updated November 18, 2026.")
    privacy += article([("about","About this policy"),("local","App data"),("google","Google & Drive"),("services","Other services"),("website","This website"),("control","Your controls"),("contact","Contact")],
        section("about","About this policy.","<p>Grants for Good (GFG) is a private beta software project by Matt Cornett for grant research and team project work. Each user runs a local application. This public website provides product information and support; it does not host a team’s working records.</p><p>Your workspace owner decides who is invited, what client information belongs in the workspace, and how team records are shared. This policy describes the app’s handling of information, not the privacy practices of every organization using it.</p>")+
        section("local","Information in the installed app.","<p>The app stores information you enter or import: client and program profiles, contacts, notes, tasks, discussions, research findings, source links, grant preparation records, activity, revision history, and related workspace settings.</p><p>Workspace records are held locally on your computer. When sharing is connected, records also sync to the Google Drive workspace folder. Private sign-in settings and Google authorization tokens are stored in the current user’s local application settings, outside the shared workspace. Tokens are not included in ordinary client reports or source/update packages.</p><p>The beta uses local user-profile file protection; it does not currently encrypt these tokens in an operating-system keychain. Protect the computer and the user account that runs the app.</p>")+
        section("google","Google sign-in and Drive access.",'''<p>Google sign-in allows the app to connect to Drive under your own account. The app receives an authorization token and account identity information, including the account name and email needed to identify the workspace participant.</p><div class="callout"><strong>The current permission is full Google Drive access.</strong><p>The beta requests <code>https://www.googleapis.com/auth/drive</code>. This Google permission can allow viewing and managing files throughout the authorized Drive. It is broader than one selected folder and is not the narrower <code>drive.file</code> permission.</p></div><p>The app’s workspace features use this permission to check access to the folder you choose; create, read, and update GFG team data files; discover other team members’ data files; and transfer workspace resources or updates when those features are used. The app is designed to keep workspace operations within the configured folder, but that application behavior does not narrow the permission granted by Google.</p><p>Workspace activity is shared with people who can access the team’s folder. Google Drive link-sharing settings can allow access beyond named team members, so choose those settings carefully. The public product website does not receive your Google authorization tokens or operate the Drive connection.</p><p>Google account data is used for the connected app features described here, not sold or used for advertising. The app does not send Google account data to an unattended language-model job. If you choose to export content and submit it to a separate research service, that is a separate disclosure you control.</p><p>You can disconnect in the app and revoke access through <a href="https://myaccount.google.com/connections">Google Account connections</a>. Google’s own handling of information is described in its <a href="https://policies.google.com/privacy">privacy policy</a>.</p>''')+
        section("services","Research, exports, and other services.","<p>The app may contact funder websites, public filing sources, and connected services when you request research updates or use configured integrations. Those services receive the requests needed for the feature and have their own terms and privacy practices.</p><p>Optional open-chat research involves exporting or opening a prepared packet and choosing to submit it to your chat service. Review the packet before sharing it. GFG does not run an unattended model job just because you use this website or open a workspace.</p><p>Instrumentl connections are optional and configured separately. Supported reads and approved actions involve that service under the connected account. A GFG research import is not permission to write to an external account.</p><p>Reports and spreadsheets can contain client-specific information and sources. Once you export or send them, copies may exist outside the app’s control. Share them only with intended recipients and follow your organization’s confidentiality rules.</p>")+
        section("website","The public website.","<p>These pages are hosted on GitHub Pages. The site does not set advertising cookies, use a third-party analytics script, create user accounts, or collect form submissions. Its fictional product tour runs in the browser and does not access workspace data.</p><p>GitHub may process standard hosting information, such as an IP address and request details. See <a href=\"https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement\">GitHub’s privacy statement</a>. Following links to another website is subject to that website’s practices.</p><p>Bug reports posted to the public GitHub issue tracker are public. Do not include confidential information in them.</p>")+
        section("control","Disconnecting, deleting, and retaining records.","<ul><li><strong>Sign out in the app</strong> to remove that installation’s saved Google sign-in tokens and profile. Local workspace records are retained. Signing out does not revoke Google’s grant.</li><li><strong>Revoke Google access</strong> in your Google Account to stop the app using that authorization. This does not delete local records or existing Drive files.</li><li><strong>Ask the workspace owner to remove team access</strong> if you leave the team. Existing exported copies and local caches need separate handling.</li><li><strong>Coordinate deletion with the workspace owner.</strong> The app retains revision history, shared records, and backups. Deleting or uninstalling application files alone may leave user settings, workspace caches, Drive files, and other teammates’ copies behind.</li></ul><p>There is no central public GFG account database to delete. Retention and removal of team records must account for shared copies, backups, and any legal or contractual obligations of the organization using the workspace.</p>")+
        section("contact","Questions and changes.","<p>For a privacy or access request, contact the person who supplied your workspace installation through your existing private channel. Developer: <a href=\"https://github.com/ZombieWalrusDong\">Matt Cornett</a>. For non-sensitive product questions, use the <a href=\"help.html\">support page</a>.</p><p>When this policy changes, its date will be updated here. Material changes should also be brought to beta users’ attention with the relevant app update.</p>"))
    page("privacy.html","Privacy policy","How the local GFG application and its public website handle workspace records, Google Drive permission, connected services, exports, and deletion.",privacy)

    terms = hero("Terms of use","A shared understanding.","Terms for using the Grants for Good private beta and this public website. Last updated November 18, 2026.")
    terms += article([("beta","Private beta"),("use","Responsible use"),("decisions","Research & decisions"),("data","Your information"),("services","Other services"),("availability","Availability"),("contact","Contact")],
        section("beta","About the private beta.","<p>Grants for Good is a software project by Matt Cornett for grant research, client context, and project work. The installed app is currently supplied directly to invited users. Publishing this website does not create a public hosted application, a paid service, or a promise of general availability.</p><p>Use an installation supplied or authorized by your workspace owner. These pages do not publish the private source code or grant rights to redistribute private client information, account configuration, or team installers.</p>")+
        section("use","Use the workspace responsibly.","<p>Use GFG only for work you are authorized to do. Use your own connected accounts, respect your organization’s confidentiality rules, and do not attempt to access someone else’s records or bypass an account or approval restriction.</p><p>You are responsible for protecting your computer, checking who has access to the shared folder, and maintaining appropriate backups. Do not place confidential client information in public bug reports.</p>")+
        section("decisions","Research supports a decision; it does not make one.","<p>Funder listings, public filings, imported findings, scores, and suggestions can be incomplete, outdated, or wrong. Confirm important information against current funder guidance before relying on it. Scores are not a probability of receiving a grant, and a high partial score is not a verified recommendation.</p><p>Human review, authorization to act, client approval, actual submission, and funder decisions are distinct events. Importing research does not authorize outreach, an application, or changes to a connected account. No funding outcome is guaranteed.</p>")+
        section("data","Your information and shared copies.","<p>GFG does not claim ownership of your client records, original notes, or other information you place in the workspace. You must have the right to use and share that information and any third-party materials, including books, reports, and grant databases.</p><p>Exports can contain sensitive details. Only send them to intended recipients. Workspace history and shared copies may remain on multiple computers or in backups; coordinate retention and deletion with the workspace owner. See the <a href=\"privacy.html\">privacy policy</a>.</p>")+
        section("services","Other services have their own rules.","<p>Google, GitHub, Instrumentl, funder websites, chat services, and other providers operate independently. Their availability, permissions, subscriptions, and terms still apply. This project is not endorsed by or affiliated with Google, GitHub, or Instrumentl.</p><p>Only use a connection in ways permitted by the relevant account owner and provider. Do not assume that app approval overrides a provider’s access rules.</p>")+
        section("availability","A beta can change or fail.","<p>The beta is provided as available, with no promise of uninterrupted operation, complete accuracy, compatibility with every computer, or fitness for a particular purpose. It may contain defects. Keep backups, verify important changes, and use an appropriate review process for consequential work.</p><p>To the extent permitted by applicable law, the developer is not responsible for losses resulting from reliance on incomplete research, service interruptions, software defects, or lost data. These terms do not remove rights that applicable law does not allow to be excluded.</p>")+
        section("contact","Questions and updates.","<p>Ask the workspace owner who supplied your installation about account or private workspace concerns. For non-sensitive product issues, see <a href=\"help.html\">Help & support</a>. Developer: <a href=\"https://github.com/ZombieWalrusDong\">Matt Cornett</a>.</p><p>The dated terms on this page may change as the beta develops. Material changes should be communicated with the relevant app update.</p>"))
    page("terms.html","Terms of use","Terms for authorized use of the GFG private beta, research review, client information, connected services, and beta availability.",terms)

    brand = hero("Brand kit","Small mark.<br>Good intentions.","A calm, legible identity for a tool that helps people do thoughtful work. Use the full name, Grants for Good; GFG is the short form.")
    brand += article([("identity","The identity"),("palette","Color & type"),("voice","The voice"),("assets","Download assets")],
        section("identity","A familiar mark, with room to grow.",'<div class="brand-plate">'+wordmark()+'</div><p>The green <strong>g.</strong> mark carries forward the identity already used in the app. A small yellow detail brings a little warmth; a straightforward wordmark keeps the name easy to recognize.</p><p>Give the mark breathing room. Keep its shape and colors intact, use a clear background, and do not place it over a busy image. Do not imply an endorsement by another organization.</p>')+
        section("palette","Forest, fresh green, and open space.",'<div class="swatches"><div class="swatch"><div class="swatch-color"></div><p><strong>Forest</strong><br>#11362D</p></div><div class="swatch"><div class="swatch-color lime"></div><p><strong>Fresh green</strong><br>#DFED95</p></div><div class="swatch"><div class="swatch-color paper"></div><p><strong>Paper</strong><br>#F8FAF6</p></div></div><p>Use forest for primary text and strong surfaces. Fresh green is a supporting highlight, not a text color on white. Paper leaves room for dense research to breathe.</p><p>Headings use Georgia, with a system sans serif for reading and interface text. No external font request is needed. Pair editorial clarity with practical, readable labels.</p>')+
        section("voice","Good work, well supported.","<p>Write like a capable colleague. Say what was found, why it matters, what is uncertain, and what happens next. Prefer a useful sentence to an unexplained badge.</p><p>Avoid inflated promises, invented impact numbers, claims of guaranteed grant wins, and language that turns a suggestion into approval. Let the source and the work speak for themselves.</p>")+
        section("assets","The working assets.",'<p>The kit contains SVG marks and wordmarks, PNG icons, a social sharing card, the palette, and brief usage notes.</p><div class="actions"><a class="button" href="assets/grants-for-good-brand-kit.zip" download>Download the brand kit</a><a class="button secondary" href="assets/wordmark.svg" download>Get the SVG wordmark</a></div><p class="caption">For identifying Grants for Good. No client information is included.</p>'))
    page("brand.html","Brand kit","Download the Grants for Good logo, wordmark, icons, color palette, and social sharing card.",brand)

    page("404.html","Page not found","Find your way back to the Grants for Good product and support website.",hero("Page not found","Let’s find your next step.","That page isn’t here. The product pages and support information are still close by.")+'<div class="wrap section"><div class="actions"><a class="button" href="index.html">Back to home</a><a class="button secondary" href="help.html">Find help</a></div></div>')
    pages = [p.name for p in ROOT.glob('*.html') if p.name != '404.html']
    (ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{ORIGIN}{name if name != "index.html" else ""}</loc><lastmod>2026-11-18</lastmod></url>' for name in sorted(pages))+'</urlset>\n')
    (ROOT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+ORIGIN+'sitemap.xml\n')
    (ROOT/'.nojekyll').touch()
    print(json.dumps({'pages':len(pages)+1,'origin':ORIGIN,'app_version':VERSION}))


if __name__ == '__main__':
    main()
